import {z} from 'zod';
import {field} from './fieldRules';

// Same labels and rules as backend/src/validations/catalog.validation.ts.
// The SKU is generated by the backend, so it is not part of the form.

const text = (label: string, max: number) =>
  field({label, kind: 'text', max, required: false});
const optionalPrice = (label: string) =>
  field({label, kind: 'price', required: false});

const variant = z.object({
  id: z.string().optional(),
  size: field({label: 'Size', kind: 'text', max: 20}),
  color: field({label: 'Color', kind: 'text', max: 30}),
  colorHex: z.string().optional(),
  mrp: optionalPrice('Variant MRP'),
  sellingPrice: optionalPrice('Variant Price'),
  isActive: z.boolean(),
  // Shown in the table only; not sent
  available: z.number().optional(),
});

export const productSchema = z
  .object({
    name: field({label: 'Product Name', kind: 'text', max: 120}),
    categoryId: z.string().min(1, 'Category is required'),
    brandId: z.string().optional(),
    gender: z.string(),
    productType: text('Product Type', 60),
    mrp: field({label: 'MRP', kind: 'price'}),
    sellingPrice: field({label: 'Selling Price', kind: 'price'}),
    taxRate: z.coerce.number(),
    fabric: text('Fabric', 60),
    pattern: text('Pattern', 60),
    fit: text('Fit', 60),
    sleeveType: text('Sleeve Type', 60),
    neckType: text('Neck Type', 60),
    occasion: text('Occasion', 60),
    season: text('Season', 60),
    careInstructions: text('Care Instructions', 300),
    shortDesc: text('Short Description', 300),
    detailedDesc: text('Detailed Description', 4000),
    tagsText: z.string().max(500).optional(),
    weightKg: z
      .union([z.string(), z.number()])
      .optional()
      .refine(
        (v) => v === undefined || v === '' || Number(v) > 0,
        'Weight must be more than 0',
      ),
    returnEligible: z.boolean(),
    returnPeriodDays: z.coerce
      .number()
      .int()
      .min(0)
      .max(30, 'Return Period can be at most 30 days'),
    seoTitle: text('SEO Title', 70),
    seoDesc: text('SEO Description', 160),
    variants: z
      .array(variant)
      .min(1, 'Add at least one variant (size / color)'),
  })
  .superRefine((v, ctx) => {
    if (v.sellingPrice > v.mrp) {
      ctx.addIssue({
        code: 'custom',
        path: ['sellingPrice'],
        message: 'Selling Price cannot be more than MRP',
      });
    }
    const seen = new Set<string>();
    v.variants.forEach((row, i) => {
      const key = `${row.size.toLowerCase()}|${row.color.toLowerCase()}`;
      if (seen.has(key)) {
        ctx.addIssue({
          code: 'custom',
          path: ['variants', i, 'size'],
          message: 'This size and color is already listed',
        });
      }
      seen.add(key);
    });
  });

export type ProductValues = z.input<typeof productSchema>;
export type ProductOutput = z.output<typeof productSchema>;

export const EMPTY_PRODUCT: ProductValues = {
  name: '',
  categoryId: '',
  brandId: '',
  gender: 'UNISEX',
  productType: '',
  mrp: '',
  sellingPrice: '',
  taxRate: 5,
  fabric: '',
  pattern: '',
  fit: '',
  sleeveType: '',
  neckType: '',
  occasion: '',
  season: '',
  careInstructions: '',
  shortDesc: '',
  detailedDesc: '',
  tagsText: '',
  weightKg: '',
  returnEligible: true,
  returnPeriodDays: 7,
  seoTitle: '',
  seoDesc: '',
  variants: [
    {
      size: '',
      color: '',
      colorHex: '',
      mrp: '',
      sellingPrice: '',
      isActive: true,
    },
  ],
};

/** Form values -> API body (tags as a list, empty values dropped) */
export const toProductBody = (v: ProductOutput) => {
  const {tagsText, weightKg, variants, ...rest} = v;
  return {
    ...rest,
    brandId: rest.brandId || undefined,
    weightKg:
      weightKg === '' || weightKg === undefined ? undefined : Number(weightKg),
    tags: (tagsText ?? '')
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean),
    variants: variants.map(({available, ...row}) => ({
      ...row,
      colorHex: row.colorHex || undefined,
    })),
  };
};
